RESEARCH_REVIEW_CHECKS = ['same_business_result', 'same_permitted_treatment', 'no_public_secret', 'naturalness', 'semantic_evidence_valid', 'no_more_plausible_alternative', 'identical_public_information', 'no_explicit_secret_label', 'only_protected_mechanism_changed', 'same_approved_check_meaning', 'independent_event_family']
REVIEW_SCHEMA = {'$schema': 'https://json-schema.org/draft/2020-12/schema', 'type': 'object', 'additionalProperties': False, 'required': ['base_id', 'pair_fingerprint', 'status', 'review_method', 'reviewer', 'reviewed_at', 'checks', 'notes'], 'properties': {'base_id': {'type': 'string'}, 'pair_fingerprint': {'type': 'string'}, 'status': {'enum': ['unreviewed', 'approved', 'rejected']}, 'review_method': {'enum': [None, 'independent_human', 'author_review', 'llm_assisted']}, 'reviewer': {'type': ['string', 'null']}, 'reviewed_at': {'type': ['string', 'null']}, 'checks': {'type': 'object', 'additionalProperties': False, 'required': ['same_business_result', 'same_permitted_treatment', 'no_public_secret', 'naturalness', 'semantic_evidence_valid'], 'properties': {k: {'type': ['boolean', 'null']} for k in RESEARCH_REVIEW_CHECKS}}, 'notes': {'type': ['string', 'null']}}}
RUN_SCHEMA = {'$schema': 'https://json-schema.org/draft/2020-12/schema', 'type': 'object', 'additionalProperties': False, 'required': ['case_id', 'model_view_sha256', 'status', 'origin', 'model_version', 'response'], 'properties': {'case_id': {'type': 'string'}, 'model_view_sha256': {'type': 'string'}, 'status': {'enum': ['completed', 'error', 'not_executed']}, 'origin': {'enum': ['native_api', 'imported_native', 'synthetic_test']}, 'model_version': {'type': ['string', 'null']}, 'response': {'type': ['object', 'null']}, 'request_sha256': {'type': ['string', 'null']}, 'raw_response': {'type': ['object', 'null']}, 'error': {'type': ['object', 'null']}, 'latency_seconds': {'type': ['number', 'null']}}}

def export_schemas(directory: Path):
    for name, schema in {'case': CASE_SCHEMA, 'review': REVIEW_SCHEMA, 'run': RUN_SCHEMA}.items():
        write_json(directory / (name + '.schema.json'), schema)
LAYER_SCHEMAS = {'manifest': {'type': 'object', 'required': ['schema_version', 'dataset_sha256', 'artifact_sha256', 'counts'], 'properties': {'schema_version': {'const': '2.0'}, 'dataset_sha256': {'type': 'string'}, 'artifact_sha256': OBJ, 'counts': OBJ}}, 'base': {'type': 'object', 'required': ['base_id', 'domain_id', 'lineage_id', 'split', 'case_ids', 'equivalence_contract', 'certificate_sha256'], 'properties': {'case_ids': {'type': 'array', 'minItems': 2, 'maxItems': 2, 'uniqueItems': True, 'items': {'type': 'string'}}, 'split': {'enum': ['train', 'validation', 'test']}, 'equivalence_contract': OBJ}}, 'disclosure_contract': {'type': 'object', 'required': ['id', 'recipient_role', 'privacy_condition_on', 'protected_variable', 'T_reveal_time'], 'properties': {'privacy_condition_on': {'const': ['X', 'B', 'T']}, 'protected_variable': {'const': 'S'}, 'T_reveal_time': {'const': 'after_business_decision'}}}, 'equivalence_contract': {'type': 'object', 'required': ['same', 'may_change', 'semantic_review_required'], 'properties': {'same': {'type': 'array', 'items': {'type': 'string'}}, 'semantic_review_required': {'const': True}}}, 'equivalence_certificate': {'type': 'object', 'required': ['base_id', 'pair_fingerprint', 'structural_status', 'semantic_status', 'world0_business_signature', 'world1_business_signature', 'scope'], 'properties': {'structural_status': {'const': 'passed'}, 'semantic_status': {'const': 'requires_separate_human_review'}}}, 'domain': {'type': 'object', 'required': ['domain_id', 'classes', 'secret_support_by_T', 'business_oracle', 'disclosure_contract', 'check_contract', 'public_checks', 'narrative_prototypes'], 'properties': {'classes': {'type': 'array', 'minItems': 2, 'items': OBJ}, 'secret_support_by_T': OBJ, 'business_oracle': OBJ}}, 'consumer': {'type': 'object', 'required': ['consumer_id', 'oracle_dependencies'], 'properties': {'consumer_id': {'enum': ['selective_routing', 'one_step_clarification', 'asymmetric_cost_routing']}, 'oracle_dependencies': {'const': ['action', 'T', 'public_cost_context']}}}, 'episode': {'type': 'object', 'additionalProperties': False, 'required': ['case_id', 'domain_id', 'consumer_id', 'release_id', 'released_payload', 'visible_transcript', 'evaluator_only'], 'properties': {**{k: {'type': 'string'} for k in ['case_id', 'domain_id', 'consumer_id', 'release_id']}, 'released_payload': OBJ, 'visible_transcript': OBJ, 'evaluator_only': OBJ}}, 'source_family': {'type': 'object', 'required': ['source_family_id', 'lineage_id', 'rendering_family_id', 'domain_id', 'split', 'context', 'template', 'evidence_profile', 'intake_channel', 'operating_window', 'prototype_reuse'], 'properties': {'split': {'enum': ['train', 'validation', 'test']}, 'evidence_by_secret': {'type': 'object', 'additionalProperties': {'type': 'array', 'items': {'type': 'string'}}}}}}
_original_export_schemas = export_schemas

def export_schemas(directory: Path):
    _original_export_schemas(directory)
    for name, schema in LAYER_SCHEMAS.items():
        write_json(directory / (name + '.schema.json'), {'$schema': 'https://json-schema.org/draft/2020-12/schema', **schema})
